   "card": {
    "fk": "Avvikelser från normal sinusrytm i frekvens, regelbundenhet eller impulsursprung – supraventrikulära (oftast smala QRS) och ventrikulära (breda QRS), brady- och takyarytmier.",
    "v": [
     "Normal vilofrekvens 50–100/min; under = bradykardi, över = takykardi.",
     "Förmaksflimmer: oregelbundet oregelbunden rytm utan P-vågor; kammarfrekvensen kan vara normal eller hög; obehandlat ökar strokerisken. Fladder: sågtandade vågor med regelbundet eller varierande AV-block.",
     "Preexcitation (deltavåg) innebär en accessorisk bana genom annulus fibrosus som ger AVRT (ortodrom eller antidrom) = WPW-syndrom; sällan farligt utom vid samtidigt förmaksflimmer, då flimmervågor kan ledas till kamrarna med mycket hög frekvens.",
     "Regelbunden smalkomplextakykardi 150–220/min med abrupt start utan synliga P: oftast AVNRT, alternativt ortodrom AVRT.",
     "Snabb bredkomplextakykardi (ofta >200/min) vid kollaps/medvetslöshet = ventrikeltakykardi.",
     "SVES är oftast ofarliga; VES som ökar eller kvarstår vid arbete innebär större risk för allvarlig arytmi.",
     "Utredning: akut EKG, troponin och NT-proBNP; polikliniskt ekokardiografi, arbets-EKG och Holter-EKG."
    ],
    "k": "Palpitationer, yrsel, (pre)synkope, dyspné, bröstsmärta, svikt; ofta intermittent. Vid förmaksflimmer varierar slagvolymen slag för slag p.g.a. varierande fyllnad.",
    "d": "12-avlednings-EKG under symtom, långtids-EKG/event-EKG/loop-registrator; elektrolyter (K, Mg, Ca), TSH, ekokardiografi.",
    "b": "Förmaksflimmer: frekvens- eller rytmkontroll, strokeriskvärdering och antikoagulation. Reentrytakykardi: vagala manövrer, adenosin, ablation. VT/kammarflimmer: defibrillering, ICD.",
    "m": "Ge inte AV-nodsblockerande läkemedel (t.ex. adenosin) vid preexciterat förmaksflimmer. Bredkomplextakykardi är VT tills motsatsen bevisats. Sjuk sinusknuta kan ge paus på ca 2 RR-intervall (SA-block/sinusarrest).",
    "src": "t4-150"
   },
