   "card": {
    "fk": "Ultraljudsundersökning av hjärtat där 2D/3D-bilder visar dimensioner, väggtjocklek och rörelse, och Doppler visar flödeshastigheter och tryckgradienter.",
    "v": [
     "Ejektionsfraktion = slagvolym/slutdiastolisk volym = (EDV−ESV)/EDV × 100; ex. (120−60)/120 = 50 %.",
     "Höga flödeshastigheter (t.ex. över stenotisk aortaklaff) mäts med kontinuerlig Doppler (m/s).",
     "Kontinuitetsekvationen: VTI(LVOT) × area(LVOT) = AVA × VTI(aortaklaff); LVOT-diametern ger arean.",
     "Systoliskt lungartärtryck skattas från trikuspidalisinsufficiensens gradient (förenklad Bernoulli 4v²) plus högerförmakstrycket.",
     "Höga fyllnadstryck: förstorat vänster förmak, högt E/A, ev. sekundär (postkapillär) pulmonell hypertension; normalt lungvensflöde är bifasiskt.",
     "Förstahandsundersökning vid blåsljud/misstänkt klaffel och för att verifiera hypertrofi; visar samtidigt kammarfunktion och klaffel.",
     "Metodval: eko har bäst tidsupplösning, DT visar kranskärl men ger strålning, MR påvisar fibros och är alternativ vid dålig ekobild."
    ],
    "k": "Bedömer kammarstorlek, väggtjocklek, systolisk (EF) och diastolisk funktion, klaffar, perikard och shuntar. HFrEF EF ≤40 %, HFmrEF 41–49 %, HFpEF ≥50 %.",
    "d": "Pulsad Doppler (bestämt djup, aliasing vid höga hastigheter), kontinuerlig Doppler (höga hastigheter), färgdoppler (regurgitation). Tät aortastenos: AVA <1 cm².",
    "b": "TTE riskfri. TEE ger bättre detaljbild (vegetationer, förmakstromber) men kräver fasta/sedering.",
    "m": "Normal EF utesluter inte hjärtsvikt (HFpEF). Tentafälla: EF räknas på slutdiastolisk – inte slutsystolisk – volym. Dåligt ekofönster vid fetma och KOL.",
    "src": "t4-033"
   },
