   "card": {
    "fk": "Aortastenos är en förträngning av aortaklaffen som tryckbelastar vänster kammare; aortainsufficiens är ett diastoliskt läckage som volymbelastar den.",
    "v": [
     "Aortastenos ger systoliskt ejektionsblåsljud i 2:a intercostalrummet höger med fortledning mot halsen; differentialdiagnoser vid systoliskt blåsljud är mitralisinsufficiens, VSD, pulmonalisstenos och trikuspidalisinsufficiens.",
     "Aortainsufficiens ger diastoliskt blåsljud och högt pulstryck; volymbelastningen ger ökad slagvolym och förstorad kammare med ökad muskelmassa (excentrisk hypertrofi).",
     "Aortastenos ger ökad afterload och myokardmassa (koncentrisk hypertrofi); EKG visar tecken på vänsterkammarhypertrofi.",
     "Gradering med eko: maxhastighet, medelgradient och klaffarea; ΔP = 4v² (3,0 m/s → 36 mmHg). Måttlig: ca 3,0–3,9 m/s, AVA 1,0–1,5 cm². Tät: ≥4,0 m/s, medelgradient ≥40 mmHg och AVA <1,0 cm².",
     "Ansträngningsutlöst yrsel/synkope: fixerat utflödesmotstånd begränsar hjärtminutvolymen, perifer vasodilatation och ischemiutlösta kammararytmier.",
     "Bikuspid aortaklaff (1–2 % prevalens, viss ärftlighet, vanlig vid Turners syndrom) ger tidigt blåsljud, stenos, insufficiens och aortadilatation.",
     "Vanligaste diagnostiska ingången är utredning av blåsljud; ekokardiografi är förstahandsundersökning."
    ],
    "k": "AS: angina, ansträngningssynkope, dyspné/svikt (sena symtom); svag fördröjd puls. AI: studsande puls, stort pulstryck; akut AI ger lungödem.",
    "d": "Ekokardiografi med Doppler (gradient, kontinuitetsekvationen, VK-funktion); EKG; DT/koronarangiografi inför operation.",
    "b": "Kirurgiskt klaffbyte, TAVI eller ev. plastik styrt av symtom, kammarpåverkan och klaffunktion.",
    "m": "Ansträngningssynkope hos äldre med systoliskt blåsljud = svår AS tills motsatsen bevisats. Vid lågt flöde kan blåsljudet bli svagare. Akut AI: tänk dissektion och endokardit.",
    "src": "t4-145"
   },
