   "card": {
    "fk": "GFR (glomerulär filtrationshastighet) är det främsta måttet på njurfunktion och viktigt för läkemedelsdosering; den mäts direkt med exogen markör eller skattas (eGFR) från kreatinin och/eller cystatin C.",
    "v": [
     "eGFR-kreatinin kräver kreatinin, ålder och kön; eGFR-cystatin C kräver cystatin C och ålder.",
     "Relativt GFR anges per 1,73 m² standardiserad kroppsyta; absolut GFR (mL/min) kräver längd och vikt och behövs vid dosering av t.ex. cytostatika och aminoglykosider.",
     "Kreatinin påverkas av muskelmassa (falskt lågt efter amputation), köttintag, sängläge och läkemedel; cystatin C av tyreoideafunktion, kortikosteroider och inflammation.",
     "Direkt mätning med iohexol- eller 51Cr-EDTA-clearance är exakt men dyr och resurskrävande (t.ex. inför njurdonation); 51Cr-EDTA med gammakamera kan ge sidoseparerad funktion men kräver isotoprum.",
     "Kreatininclearance med dygnsurin är föråldrat.",
     "Prover vid njursjukdom: P-kreatinin och P-cystatin C (GFR), U-albumin (glomerulärt läckage) och U-IgG (oselektivt läckage)."
    ],
    "k": "Normal GFR ca 120 mL/min hos unga vuxna; sjunker med åldern. Kreatinin bildas i muskulatur, cystatin C konstant i alla kärnförande celler.",
    "d": "Vid första bedömning: använd båda markörerna (eGFR-medel). Direkt mätning när formlernas förutsättningar brister (extrem kroppskonstitution, amputation, barn, graviditet).",
    "b": "–",
    "m": "Kreatininblinda området: GFR kan sjunka 30–40 % med normalt kreatinin vid liten muskelmassa. Tentafälla: efter amputation – välj cystatin C.",
    "src": "t4-231"
   },
