   "card": {
    "fk": "Spirometri mäter volymer och flöden vid forcerad utandning (FEV1, FVC/VK, FEV1/VK) och visar obstruktiv eller restriktiv lungfunktionsnedsättning; flöde-volymkurvan visar flödet mot utandad volym.",
    "v": [
     "Obstruktivitet: FEV1/VK (FEV1/FVC) under normalområdet med nedsatt FEV1; kurvan blir konkav (urgröpt).",
     "Restriktivt mönster: små volymer (FEV1 och FVC) med normal eller hög kvot och normalformad men liten kurva; säker diagnos kräver mätt TLC.",
     "Reversibilitet: FEV1-ökning ≥12 % och ≥200 ml efter bronkdilaterare är signifikant (talar för astma); t.ex. 8 %/100 ml är icke reversibel.",
     "Obstruktivitet med nedsatt diffusionskapacitet talar för alveolär påverkan, t.ex. emfysem/KOL.",
     "Utvidgad spirometri på klinisk fysiologi omfattar även totala lungvolymer och diffusionskapacitet; vidare utredning kan vara PEF, reversibilitetstest och statisk spirometri.",
     "Preoperativ spirometri ingår i riskbedömning vid hjärt- och lungsamsjuklighet; efter pneumoni görs kontrollröntgen och ev. spirometri."
    ],
    "k": "Värden anges i liter, % av förväntat och z-score; LLN = 5:e percentilen.",
    "d": "Dynamisk spirometri före och ca 15 min efter kortverkande β2-agonist; kroppspletysmografi för TLC/RV; DLCO vid misstänkt parenkymsjukdom.",
    "b": "–",
    "m": "Låg VC med normal kvot är inte detsamma som restriktivitet (kan vara ofullständig utandning eller luftfångst). Spirometri ensamt ställer ingen diagnos.",
    "src": "t4-032"
   },
