   "card": {
    "fk": "Tillstånd där hjärtat inte kan pumpa tillräckligt med blod för vävnadernas behov, eller bara klarar det med förhöjda fyllnadstryck; indelas efter ejektionsfraktion (HFrEF, HFmrEF, HFpEF).",
    "v": [
     "NT-proBNP (eller BNP) är den centrala laboratoriemarkören: kraftigt förhöjt värde ger stark misstanke om hjärtsvikt och normalt värde gör hjärtsvikt mycket osannolik.",
     "NT-proBNP stiger även vid kammaruttänjning av annan orsak, ischemi och inflammation, och normaliseras när svikten behandlats.",
     "Utredning: NT-proBNP och ekokardiografi; vid dyspné även EKG, blodstatus (anemi), elektrolyter, troponin, saturation och ev. spirometri.",
     "Klassificering sker efter ejektionsfraktion, mätt med ekokardiografi (ibland MR): HFrEF ≤40 %, HFmrEF 41–49 %, HFpEF ≥50 %.",
     "Förhöjt troponin vid svikt kan spegla myokardbelastning snarare än infarkt.",
     "Högersvikt vid lungsjukdom (cor pulmonale): underbensödem, halsvenstas, leverförstoring och ascites.",
     "Debut av förmaksflimmer kan utlösa svikt genom förlorad förmakskontraktion och minskad fyllnad (preload)."
    ],
    "k": "Vänstersvikt: dyspné, ortopné, rassel, lungödem. Högersvikt: halsvenstas, pittingödem, hepatomegali, ascites. Vanligaste orsaker hypertoni och ischemisk hjärtsjukdom.",
    "d": "EKG + NT-proBNP; ekokardiografi (LVEF, fyllnadstryck, klaffar); lungröntgen (stas, Kerley B, pleuravätska); MR/DT vid oklar genes.",
    "b": "Behandla orsaken (hypertoni, ischemi, klaffel, arytmi), sviktläkemedel, ev. CRT/ICD och rehabilitering.",
    "m": "Normal EF utesluter inte hjärtsvikt (HFpEF). NT-proBNP och troponin kan vara förhöjda vid njursvikt, lungemboli och sepsis. Akut lungödem är livshotande.",
    "src": "t4-131"
   },
