   "card": {
    "fk": "Tryckstegring när volymen hjärnvävnad, blod eller likvor ökar i det oeftergivliga kraniet mer än vad som kan kompenseras, med sänkt cerebralt perfusionstryck och risk för inklämning.",
    "v": [
     "En expansiv process ger dels lokala symtom genom destruktion och kompression av nerver och kärl, dels generell tryckökning.",
     "Volymökningen kompenseras först genom undanträngning av likvor (ventriklar) och venblod; när kompensationen är uttömd stiger trycket accelererande tills hjärncirkulationen upphör.",
     "Staspapill uppstår när trycket fortplantas i synnervens subaraknoidalrum, komprimerar vener och ger ödem i papillen; ögonbottenspegling bedömer papill och kärl.",
     "Inklämning sker under falx (gyrus cinguli), vid tentoriumslitsen (uncus) och i foramen magnum (cerebellartonsiller) med kompression av närliggande kärl och nerver.",
     "Sänkt vakenhet, t.ex. av intrakraniell expansivitet, måste uteslutas vid demensutredning eftersom demens inte kan bedömas vid medvetandepåverkan."
    ],
    "k": "Huvudvärk (värst på morgonen), kräkningar, sänkt medvetandegrad, staspapill; unkal herniering ger ipsilateral pupilldilatation; sent Cushings reflex.",
    "d": "Medvetandegrad (RLS/GCS), pupiller, fokala tecken; akut CT hjärna; ögonbottenundersökning.",
    "b": "Behandla orsaken (utrymning, shunt/dränage, kortikosteroider vid tumörödem); höjd huvudända, osmoterapi, ev. dekompressiv kraniektomi.",
    "m": "Lumbalpunktion vid förhöjt tryck kan utlösa inklämning – CT/ögonbotten före LP. Ensidigt vidgad, ljusstel pupill med sjunkande medvetande = unkal herniering tills motsatsen bevisats.",
    "src": "t4-181"
   },
