   "card": {
    "fk": "Myokardnekros orsakad av akut ischemi, oftast trombotisk ocklusion av ett kranskärl efter plackruptur; delas i STEMI och NSTEMI.",
    "v": [
     "Akut hjärtinfarkt är arbetsdiagnosen vid akut bröstsmärta tills den uteslutits.",
     "Biokemisk markör är troponin T (eller I); diagnosen kräver minst ett förhöjt värde samt dynamisk förändring.",
     "Utesluta infarkt: upprepade EKG och troponin T (t.ex. ×3) under rytmövervakning.",
     "STEMI: ST-höjningar i intilliggande avledningar (t.ex. inferiort II, III, aVF) med reciproka ST-sänkningar; kräver omedelbar reperfusion med PCI.",
     "Bröstsmärta med nytillkommet vänstergrenblock handläggs som STEMI; posterior infarkt ger endast reciproka ST-sänkningar i V1–V3.",
     "Ischemitecken på EKG med troponindynamik utan ST-höjning = NSTEMI; QS-komplex anteroseptalt talar för genomgången infarkt.",
     "Död i akutskedet orsakas av rytmrubbningar, kardiogen chock och hjärttamponad (ruptur)."
    ],
    "k": "Bröstsmärta, ev. dyspné, illamående, kallsvett; tysta infarkter hos diabetiker och äldre. Typ 2-infarkt vid obalans syrebehov/tillförsel (anemi, takyarytmi).",
    "d": "EKG direkt och upprepat; troponin (stiger 3–6 h, topp 12–24 h); ekokardiografi; koronarangiografi.",
    "b": "STEMI: primär PCI (trombolys om PCI inte hinns med), därefter antitrombotisk behandling och sekundärprevention.",
    "m": "Vänta inte på troponin vid STEMI. Normalt EKG utesluter inte infarkt. Ny mitralisinsufficiens eller chock dag 3–7: tänk papillarmuskel-, septum- eller väggruptur.",
    "src": "t4-138"
   },
