     "Urinblåsecancer: muskelinvasiv tumör motsvarar T2–T4; T2a = invasion i inre halvan och T2b i yttre halvan av muskellagret. Muskelinvasiv cancer behandlas kurativt oftast med cystektomi (alternativt kemoradioterapi).",
