    "fk": "Substanser i blod eller andra kroppsvätskor vars koncentration speglar förekomst eller mängd av tumörsjukdom; används främst för uppföljning och recidivupptäckt, inte för screening.",
    "v": [
     "CA 125 är tumörmarkör vid epitelial (serös) ovarialcancer men har låg sensitivitet (särskilt i stadium I–II) och låg specificitet.",
     "CA 125 stärker misstanken vid diagnos och är mest användbar för uppföljning om den var förhöjd vid diagnos; stigande värde talar för recidiv.",
     "CEA förhöjs vid flera cancrar och vid inflammation; begränsad diagnostisk nytta men användbar vid känd sjukdom och spridning (t.ex. kolorektalcancer).",
     "Andra gynekologiska markörer: inhibin (granulosacellstumör) och hCG (trofoblast-/könscellstumörer)."
    ],
    "k": "Exempel: PSA (prostata), CEA (kolorektal), CA 125 (ovarial), AFP (HCC, könscellstumör), hCG, CA 19-9 (pankreas), M-komponent (myelom).",
    "d": "Förändring över tid är viktigast; använd samma metod och laboratorium vid seriella prover. Diagnos ställs med bilddiagnostik och PAD.",
    "b": "–",
    "m": "Normalt värde utesluter inte cancer. CA 125 är förhöjt även vid endometrios, graviditet, peritonit och efter bukkirurgi. Ingen markör lämpar sig för allmän screening.",
