   "card": {
    "fk": "Malign epitelial tumör i endometriet och den vanligaste gynekologiska cancern i Sverige; delas i östrogenberoende endometrioid typ (~85 %) och icke-endometrioida typer (serös, klarcellig).",
    "v": [
     "Postmenopausal blödning ska misstänkas vara endometriecancer (differentialdiagnoser endometriehyperplasi och EIN).",
     "Riskfaktorer: obesitas, diabetes, hypertoni, infertilitet/anovulation/PCOS, endometriehyperplasi, östrogenbehandling utan gestagen och hereditet (Lynch).",
     "Övervikt ökar risken eftersom aromatas i fettväven omvandlar androstendion till estron; hyperöstrogenismen ger hyperplasi och cancer (typ 1).",
     "Diagnosen ställs oftast i tidigt stadium eftersom tumören ger tidig blödning.",
     "Endometrioid adenocarcinom: kribrösa körtlar, ofta skivepitelmetaplasi; FIGO grad 1 vid låggradig atypi och liten solid andel.",
     "Klarcellscancer: adenocarcinom med kärnatypi och klar cytoplasma."
    ],
    "k": "Endometrioid typ kring 60 år, föregås av atypisk hyperplasi, god prognos. Serös typ hos äldre i atrofiskt endometrium, TP53-mutation, dålig prognos.",
    "d": "Anamnes (menopaus, HRT, avföring, miktion, smärta, nattsvett, vikt, tidigare tumörer, hereditet), vaginalt ultraljud (endometrietjocklek), endometrieprov; MRT/CT för stadium.",
    "b": "Hysterektomi med bilateral salpingooforektomi, ev. lymfkörtelstaging; adjuvant behandling efter risk.",
    "m": "Serös typ kan spridas trots liten tumör. MMR-defekt tumör hos ung patient: misstänk Lynch syndrom.",
    "src": "t4-272"
   },
