     "Vanligaste genetiska förändringen är APC-mutation (ca 80 %).",
     "Vid ulcerös kolit korrelerar cancerrisken med debutålder, utbredning och antal skov (duration).",
     "Debutsymtom: blod i avföringen, anemi och ändrade avföringsvanor; blod i avföringen kräver att GI-malignitet utesluts.",
