    "k": "Blödningsfrågeställning: oväntad blödning vid ingrepp, blåmärken, riklig mens, ledblödningar. Trombosfrågeställning: VTE i ung ålder, oprovocerad/recidiverande trombos, ovanlig lokal, hereditet.",
    "d": "Vid misstänkt trombos: D-dimer, APTT, PK-INR, fibrinogen, blodstatus med diff, CRP och elektrolyter. Blandningsprov: korrigering = faktorbrist, ingen korrigering = hämmare.",
