    "k": "Kärnbegrepp: Schiffbas bildas först reversibelt och omlagras sedan irreversibelt till ketoamin (HbA1c). Hastigheten beror på glukoskoncentration och erytrocytens livslängd (ca 120 dagar).",
    "d": "Anges i mmol/mol; diagnosgräns för diabetes ≥48 mmol/mol. Tolka alltid mot blodstatus; vid oväntat lågt värde tänk erytrocytöverlevnad, hemoglobinopati, transfusion och HbF.",
