   "card": {
    "fk": "Malign epitelial tumör i livmoderhalsen, nästan alltid orsakad av persisterande högrisk-HPV, som föregås av cervikal intraepitelial neoplasi (LSIL/CIN1 och HSIL/CIN2–3).",
    "v": [
     "Persisterande högrisk-HPV (främst typ 16 och 18) orsakar neoplasin; E6 inaktiverar p53 och E7 inaktiverar pRb.",
     "Neoplasin uppstår i transformationszonen där omoget metaplastiskt skivepitel är mål för HPV.",
     "HSIL kännetecknas av anisokaryos, ökad kärn-cytoplasmakvot och grovt kromatin genom större delen av epitelet; genombrott av basalmembranet innebär (mikro)invasiv skivepitelcancer.",
     "Adenocarcinoma in situ (AIS) är förstadiet till adenocarcinom och utgår från cylinderepitelet i cervikalkanalen.",
     "Anamnes vid cellförändringar: menarche, cykel, kontraception, sexualdebut, partners, graviditeter/aborter, tidigare cellförändringar samt allmän anamnes.",
     "Undersökning: inspektion, nytt cellprov, pensling med ättiksyra/jod, kolposkopi med riktade biopsier, bimanuell palpation och vaginalt ultraljud."
    ],
    "k": "Förstadier är symtomfria; cancer ger kontaktblödning, mellanblödning och flytning, sent smärta och hydronefros. Riskfaktorer för HPV-persistens: rökning, p-piller, immunsuppression.",
    "d": "Screening med primär HPV-analys och reflexcytologi (23–64 år). Kolposkopi: acetovita och jodnegativa områden styr biopsi. PAD: p16-blockpositivitet och högt Ki-67 stöder HSIL. Cancer: MRT bäcken, CT, FIGO-stadium.",
    "b": "HSIL: slyngexcision (LEEP/konisering). Tidig cancer: kirurgi; lokalt avancerad: kemoradioterapi. Primärprevention med HPV-vaccin.",
    "m": "AIS och adenocarcinom sitter högt i kanalen och upptäcks sämre med cytologi. Många HPV-infektioner och LSIL läker ut spontant.",
    "src": "t4-268"
   },
