   "card": {
    "fk": "Myelom är en malign klonal proliferation av plasmaceller i benmärgen med produktion av monoklonalt immunglobulin (M-komponent) och skelettdestruktion; plasmocytom är en isolerad plasmacellstumör.",
    "v": [
     "Benmärgsbiopsin visar hög cellularitet med CD138-positiva monoklonala plasmaceller med lätt kedje-restriktion (antingen kappa eller lambda) och negativ cytokeratin (AE1/AE3), vilket skiljer från carcinommetastas.",
     "Anemin beror främst på att myelomet tränger undan övrig hematopoes; inflammation och njursvikt bidrar.",
     "Antikroppsförsvaret är klart nedsatt eftersom den polyklonala immunglobulinproduktionen är undertryckt och nästan bara det monoklonala immunglobulinet finns.",
     "Komplikationer: hyperkalcemi, njursvikt, anemi och osteolyser (CRAB) samt AL-amyloidos, infektioner p.g.a. immunbrist och neurologiska symtom.",
     "Kraftigt förhöjd SR beror på höga immunglobulinnivåer, inflammation med förhöjt fibrinogen och anemi.",
     "Skelettutredning görs med bilddiagnostik av skelettet för osteolyser och kalciumanalys för hyperkalcemi."
    ],
    "k": "Äldre patient med skelettsmärta/patologiska frakturer, anemi, trötthet, infektioner, njursvikt och hyperkalcemi. Rouleaux-bildning i blodutstryk.",
    "d": "S-/P-proteinelektrofores med immunfixation, fria lätta kedjor i serum och urinelfores. Benmärgsundersökning (klonala plasmaceller). Blodstatus, kreatinin, kalcium, β2-mikroglobulin; DT/MR skelett.",
    "b": "–",
    "m": "Tentafälla: lättkedjemyelom och icke-sekretoriskt myelom syns inte som M-komponent i serum – fria lätta kedjor och urinelfores behövs. Akuta komplikationer: hyperkalcemi, ryggmärgskompression, njursvikt, hyperviskositet.",
    "src": "t4-437"
   },
