   "card": {
    "fk": "Malign epitelial tumör utgången från njurtubulusepitel (adenocarcinom/renal cell carcinoma), vanligast hos äldre män.",
    "v": [
     "Klarcellig njurcancer är den vanligaste typen.",
     "Vid klarcellig njurcancer inaktiveras tumörsuppressorgenen VHL (kromosom 3p).",
     "VHL-inaktivering gör att HIF-1/HIF-2 inte bryts ned, vilket ger ökad angiogenes (VEGF) och förändrad metabolism.",
     "Riskfaktorer: rökning, övervikt, hypertoni, njursvikt, östrogen, tungmetaller, asbest, petroleumprodukter och ärftlighet.",
     "Njurcancer upptäcks ofta incidentellt vid bilddiagnostik.",
     "Histologiskt har klarcellig cancer celler med klar, lipid- och glykogenrik cytoplasma i solida bon med rikt tunnväggigt kärlnät."
    ],
    "k": "Hematuri, flanksmärta och palpabel resistens (sällan alla tre). Paraneoplastiskt: polycytemi, hyperkalcemi, hypertoni, feber, hög SR. Växer gärna in i njurvenen; metastaserar till lungor och skelett.",
    "d": "CT buk/thorax med kontrast; ultraljud skiljer solid tumör från cysta. PAD med subtyp, WHO-ISUP-grad och pTNM.",
    "b": "Partiell eller radikal nefrektomi; metastaserad sjukdom behandlas med målriktad/immunologisk terapi.",
    "m": "Makroskopisk hematuri ska alltid utredas. Oförklarad polycytemi eller hyperkalcemi kan vara första tecknet.",
    "src": "t4-222"
   },
