   "card": {
    "fk": "Systemisk autoimmun sjukdom med autoantikroppar mot kärnantigen och immunkomplexmedierad inflammation i hud, leder, njurar, serösa hinnor, blod och CNS.",
    "v": [
     "Incidensen är ca 2–8/100 000; sjukdomen är 6–8 gånger vanligare hos kvinnor och debuterar oftast i fertil ålder.",
     "Etiologin är ett samspel mellan gener (bl.a. HLA, ca 10 % har nära släkting med SLE) och miljö (t.ex. UV-ljus, läkemedel).",
     "ANA är positiv hos nästan alla; anti-Sm och anti-dsDNA har hög specificitet.",
     "Låga komplementfaktorer (lågt C4, C1q) beror på konsumtion vid immunkomplexbildning.",
     "Organmanifestationer: glomerulonefrit, hjärt- och lungpåverkan, serosit, cytopenier (anemi, trombocytopeni), CNS-symtom och munsår.",
     "Sekundärt antifosfolipidsyndrom ger tromboser och missfall; andfåddhet kan bero på lungemboli och måste prioriteras."
    ],
    "k": "Ung kvinna med skovvisa diffusa symtom: ledvärk, fjärilsexantem, fotosensitivitet, munsår, serosit, tromboser och missfall.",
    "d": "Anamnes om fotosensitivitet, serositer, munsår, missfall, tromboser och läkemedel. Blodstatus, SR, CRP, kreatinin, urinsticka, ANA, ENA, anti-dsDNA, komplement; vid ledsymtom även RF och CCP för differentialdiagnos.",
    "b": "Hydroxiklorokin till de flesta; glukokortikoider och immunsuppression vid organengagemang; solskydd.",
    "m": "Differentialdiagnoser: RA, Sjögren, reaktiv artrit och infektion. Lupusnefrit kan vara symtomfri – följ urinsticka och kreatinin. Anti-SSA ger risk för kongenitalt hjärtblock hos fostret.",
    "src": "t4-467"
   },
