    "k": "Smygande episodisk minnesstörning, sedan desorientering, afasi, apraxi och beteendeförändringar. Kortikal atrofi med hippocampusatrofi.",
    "d": "Demensutredning med anamnes från anhörig, kognitiva test och uteslutning av reversibla orsaker. CT/MRT, likvor (sänkt Aβ42, förhöjt T-tau och P-tau), ev. PET. Definitiv diagnos neuropatologiskt.",
    "b": "Symtomatiskt med kolinesterashämmare och memantin; ingen behandling stoppar sjukdomen.",
    "m": "Tentafälla: skilj symtomatisk behandling (kolinesterashämmare, memantin) från sjukdomsmodifierande anti-amyloidantikroppar (lekanemab, donanemab), som godkändes i EU 2025 för tidig Alzheimer med strikta urvalskriterier. Plack och nystan finns även hos kognitivt friska äldre. Uteslut behandlingsbara orsaker (B12-brist, hypotyreos, subduralhematom, depression).",
