    "k": "Ensidig debut med vilotremor, rigiditet (kugghjulsfenomen), bradykinesi, senare postural instabilitet. Icke-motoriskt: luktnedsättning, förstoppning, REM-sömnstörning, ortostatism, depression, demens. Avpigmenterad substantia nigra.",
    "d": "Klinisk diagnos med gott svar på L-dopa. DaT-scan visar presynaptisk dopaminerg brist. MRT för att utesluta vaskulär eller strukturell orsak; neuropatologisk bekräftelse post mortem.",
    "b": "L-dopa (med dekarboxylashämmare), dopaminagonister, MAO-B- och COMT-hämmare; djup hjärnstimulering i avancerad sjukdom. Behandlingen bromsar inte förloppet.",
    "m": "Tentafälla: demens inom 1 år från motorisk debut klassas som Lewykroppsdemens. Symmetrisk debut, tidiga fall eller dåligt L-dopa-svar – tänk Parkinson-plus. Kontrollera läkemedel (antipsykotika, metoklopramid).",
