    "k": "Epiduralt: lucidt intervall på några timmar, sedan snabb medvetandesänkning. Subduralt: riskgrupper äldre, alkoholmissbrukare, antikoagulerade och spädbarn; kroniskt ger huvudvärk, konfusion och kan efterlikna demens.",
