    "fk": "Hinder för urinflödet mellan njurbäcken och uretra som ger tryckstegring och dilatation (hydronefros) och kan leda till parenkymatrofi, infektion och postrenal njursvikt.",
    "v": [
     "Hydronefros är dilaterat njurbäcken och njurkalkar med atrofi av njurparenkymet.",
     "Postrenala orsaker: uretärsten, urotelial tumör i uretär/blåsa, prostatahyperplasi, graviditet, vesikoureteral reflux och retroperitoneal fibros.",
     "Residualurin mäts med bladderscan (ultraljud) eller steril tappningskateter direkt efter miktion.",
     "Blåsutloppshinder ger trabekulering och divertiklar i blåsväggen; långvarigt hinder ger hydronefros och njursvikt.",
     "Vid uretärsten ska återbesök ske inom ca 3 veckor för att undvika kvarstående avflödeshinder och njurskada."
    ],
    "k": "Unilateralt hinder kan vara tyst; bilateralt ger oliguri/anuri. Blåsutloppshinder: trängningar, svag stråle, residualurin. Stas gynnar infektion och stenbildning.",
